sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    // Function to link a group with roles
    function linkGroupWith(grpSysId, roles) {
        if (grpSysId && Array.isArray(roles) && roles.length > 0) {
            for (var i = 0; i < roles.length; i++) {
                var grRole = new GlideRecord('sys_group_has_role');
                grRole.initialize();
                grRole.group = grpSysId;
                grRole.role = roles[i];
                grRole.insert();
            }
            gs.info("Roles assigned to the group: " + roles.join(", "));
            return true;
        } else {
            gs.info("scrip123 Roles is not an array or group ID is missing");
            return false;
        }
    }

    // Function to get role names from role sys_ids
    function getRoleNames(roleIds) {
        var roleNames = [];
        if (Array.isArray(roleIds) && roleIds.length > 0) {
            for (var i = 0; i < roleIds.length; i++) {
                var grRole = new GlideRecord('sys_user_role');
                if (grRole.get(roleIds[i])) {
                    roleNames.push(grRole.name.toString());
                }
            }
        }
        return roleNames.join(",");
    }

    // Implement resource here
    var requestBody = request.body.data;
    var groupName = requestBody.groupName;
    var roles = requestBody.roles;

    if (!groupName) {
        response.setStatus(400);
        response.setBody({
            error: "Missing required parameter: groupName",
            success: false,
            status: "Error"
        });
        return;
    }

    // Check if group already exists
    var gr = new GlideRecord('sys_user_group');
    gr.addQuery('name', groupName);
    gr.query();

    var grpSysId;
    var isNewGroup = false;

    if (gr.next()) {
        // Group already exists
        grpSysId = gr.getUniqueValue();
        linkGroupWith(grpSysId, roles);
    } else {
        // Create new group
        isNewGroup = true;
        gr.initialize();
        gr.name = groupName;
        gr.description = "This Group is created From SAM Implementation Framework";
        gr.insert();
        grpSysId = gr.getUniqueValue();
        linkGroupWith(grpSysId, roles);
    }

    // Get the role names for display
    var roleNames = getRoleNames(roles);

    // Now update the system properties to include the new group
    var grProperty = new GlideRecord('sys_properties');
    grProperty.addQuery('name', 'sam.implementation.user.groups');
    grProperty.query();

    if (grProperty.next()) {
        // Property exists, append new group to existing array
        try {
            var currentValue = JSON.parse(grProperty.getValue('value'));

            // Create the new group object
            var newGroupObj = {
                "Group": groupName,
                "Description": "This Group is created From SAM Implementation Framework",
                "Contains_roles": roleNames,
                "key": groupName.split(' ').pop(),
                "url": "sys_user_group_list.do?sysparm_query=name%3D" + encodeURIComponent(groupName) + "&sysparm_first_row=1"
            };

            // Check if group already exists in the property
            var groupExists = false;
            for (var i = 0; i < currentValue.length; i++) {
                if (currentValue[i].Group === groupName) {
                    currentValue[i] = newGroupObj; // Update existing entry
                    groupExists = true;
                    break;
                }
            }

            // Add new group if it doesn't exist
            if (!groupExists) {
                currentValue.push(newGroupObj);
            }

            // Update property with new array
            grProperty.setValue('value', JSON.stringify(currentValue));
            grProperty.update();
        } catch (e) {
            gs.error("Error updating system property: " + e);
            response.setStatus(500);
            response.setBody({
                error: "Error updating system property: " + e,
                success: false,
                status: "Error"
            });
            return;
        }
    } else {
        // Property doesn't exist, create it with initial array
        grProperty.initialize();
        grProperty.name = 'sam.implementation.user.groups';

        var initialValue = [{
            "Group": groupName,
            "Description": "This Group is created From SAM Implementation Framework",
            "Contains_roles": roleNames,
            "key": groupName.split(' ').pop(),
            "url": "sys_user_group_list.do?sysparm_query=name%3D" + encodeURIComponent(groupName) + "&sysparm_first_row=1"
        }];

        grProperty.value = JSON.stringify(initialValue);
        grProperty.insert();
    }

    // Set response
    if (isNewGroup) {
        response.setBody({
            message: "Group created successfully and system properties updated!",
            success: true,
            status: "success",
            sysId: grpSysId
        });
    } else {
        response.setBody({
            message: "Group already exists. Roles and system properties updated!",
            success: true,
            status: "success",
            sysId: grpSysId
        });
    }

})(request, response);
